CREATE TABLE IF NOT EXISTS sc_business (id TINYINT PRIMARY KEY, json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sc_admin (id TINYINT PRIMARY KEY, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sc_sessions (token_hash CHAR(64) PRIMARY KEY, csrf CHAR(64) NOT NULL, expires BIGINT NOT NULL, INDEX(expires)) ENGINE=InnoDB DEFAULT CHARSET=ascii;
CREATE TABLE IF NOT EXISTS sc_appointments (id CHAR(36) PRIMARY KEY, code CHAR(10) NOT NULL UNIQUE, barber_id INT NOT NULL, date DATE NOT NULL, start SMALLINT NOT NULL, duration SMALLINT NOT NULL, name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, payment_method VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL, request_key VARCHAR(100) UNIQUE, request_hash CHAR(64), slot_key VARCHAR(100) UNIQUE, services_json LONGTEXT NOT NULL, total INT, price_from TINYINT NOT NULL DEFAULT 0, INDEX sc_day(date,barber_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sc_email_outbox (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_attempt BIGINT NOT NULL DEFAULT 0, last_error VARCHAR(255), created_at VARCHAR(40) NOT NULL, INDEX(status,next_attempt), FOREIGN KEY(booking_id) REFERENCES sc_appointments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sc_rate_limits (id CHAR(64) PRIMARY KEY, attempts INT NOT NULL, expires BIGINT NOT NULL, INDEX(expires)) ENGINE=InnoDB DEFAULT CHARSET=ascii;
CREATE TABLE IF NOT EXISTS sc_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(80) NOT NULL, entity_id VARCHAR(100), created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
